description:
Implement `useVirtualizedVariable` for virtual scrolling where items have different heights. Pre-compute cumulative offsets to efficiently determine the visible range for any scroll position.

**Example:**
```tsx
const items = messages; // items have varying heights

function Feed() {
  const { virtualItems, totalHeight, onScroll } = useVirtualizedVariable({
    items,
    getItemHeight: (item) => item.text.length > 100 ? 80 : 40,
    containerHeight: 500,
  });

  return (
    <div style={{ height: 500, overflow: 'auto' }} onScroll={onScroll}>
      <div style={{ height: totalHeight, position: 'relative' }}>
        {virtualItems.map(({ index, item, offsetY, height }) => (
          <div key={index} style={{ position: 'absolute', top: offsetY, height }}>
            {item.text}
          </div>
        ))}
      </div>
    </div>
  );
}
```

