import { useState, useMemo, useCallback } from 'react';

type VirtualItem<T> = { index: number; item: T; offsetY: number; height: number };

type UseVirtualizedVariableOptions<T> = {
  items: T[];
  getItemHeight: (item: T, index: number) => number;
  containerHeight: number;
};

export function useVirtualizedVariable<T>({
  items,
  getItemHeight,
  containerHeight,
}: UseVirtualizedVariableOptions<T>) {
  const [scrollTop, setScrollTop] = useState(0);

  const { offsets, totalHeight } = useMemo(() => {
    const offsets: number[] = [];
    let cumulative = 0;
    for (let i = 0; i < items.length; i++) {
      offsets.push(cumulative);
      cumulative += getItemHeight(items[i], i);
    }
    return { offsets, totalHeight: cumulative };
  }, [items, getItemHeight]);

  const virtualItems = useMemo(() => {
    const overscan = 2;
    const result: VirtualItem<T>[] = [];
    for (let i = 0; i < items.length; i++) {
      const offsetY = offsets[i];
      const height = getItemHeight(items[i], i);
      if (offsetY + height < scrollTop - overscan * 40) continue;
      if (offsetY > scrollTop + containerHeight + overscan * 40) break;
      result.push({ index: i, item: items[i], offsetY, height });
    }
    return result;
  }, [items, offsets, getItemHeight, scrollTop, containerHeight]);

  const onScroll = useCallback((e: React.UIEvent<HTMLElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  return { virtualItems, totalHeight, onScroll };
}
